import{_ as t,c as a,o as r,a3 as o}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Mantenimiento de Cubiertas","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/mantenimientoCubiertas/index.md","filePath":"reportes/mantenimientoCubiertas/index.md","lastUpdated":1759946186000}'),n={name:"reportes/mantenimientoCubiertas/index.md"};function l(s,e,i,d,c,g){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="mantenimiento-de-cubiertas" tabindex="-1">Mantenimiento de Cubiertas <a class="header-anchor" href="#mantenimiento-de-cubiertas" aria-label="Permalink to &quot;Mantenimiento de Cubiertas&quot;">​</a></h1><p>Este reporte esta pensado para gestionar y consultar las intervenciones realizadas sobre los neumáticos (cubiertas) de vehículos o equipos.</p><h2 id="_1-zona-de-filtros-izquierda" tabindex="-1">1. Zona de Filtros (Izquierda) <a class="header-anchor" href="#_1-zona-de-filtros-izquierda" aria-label="Permalink to &quot;1. Zona de Filtros (Izquierda)&quot;">​</a></h2><p>Esta área te permite <strong>limitar la información</strong> que ves en la tabla principal.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Elemento del Filtro</th><th style="text-align:left;">Uso / Función</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Unidad</strong></td><td style="text-align:left;">Permite filtrar los registros para ver solo el mantenimiento realizado a una <strong>unidad de vehículo o equipo</strong> específica.</td></tr><tr><td style="text-align:left;"><strong>Referencia</strong></td><td style="text-align:left;">Permite filtrar por la <strong>referencia</strong> asociada al mantenimiento o a la cubierta.</td></tr><tr><td style="text-align:left;"><strong>Proveedor</strong></td><td style="text-align:left;">Permite filtrar los registros según el <strong>proveedor o taller</strong> que realizó el servicio (ej: &quot;Pyl Neumáticos&quot;, &quot;Gomería Axion&quot;).</td></tr><tr><td style="text-align:left;"><strong>fechaDesde / fechaHasta</strong></td><td style="text-align:left;">Permite <strong>establecer un rango de tiempo</strong> para la consulta. Solo se mostrarán los mantenimientos que hayan ocurrido entre estas dos fechas.</td></tr><tr><td style="text-align:left;"><strong>Aplicar / Restablecer</strong></td><td style="text-align:left;"><strong>Aplicar:</strong> Ejecuta los filtros seleccionados y actualiza la tabla. <strong>Restablecer:</strong> Borra todos los filtros y vuelve a mostrar la información completa (o la vista por defecto).</td></tr></tbody></table><h2 id="_2-zona-de-reporte-centro-y-derecha" tabindex="-1">2. Zona de Reporte (Centro y Derecha) <a class="header-anchor" href="#_2-zona-de-reporte-centro-y-derecha" aria-label="Permalink to &quot;2. Zona de Reporte (Centro y Derecha)&quot;">​</a></h2><p>Esta es la tabla principal donde se muestra la información detallada de cada intervención de mantenimiento.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Columna</th><th style="text-align:left;">Significado / Interpretación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ABIERTO</strong> o <strong>CERRADA</strong></td><td style="text-align:left;">Indica el estado de la intervención. Con el título &quot;ABIERTO&quot; solo muestra tareas pendientes, recientes. &quot;CERRADA&quot; es porque ya se cerraron</td></tr><tr><td style="text-align:left;"><strong>FECHA</strong></td><td style="text-align:left;">La fecha y hora en la que se registró la intervención o se realizó el trabajo.</td></tr><tr><td style="text-align:left;"><strong>PATENTE</strong></td><td style="text-align:left;">La matrícula o código de la <strong>unidad/vehículo</strong> al que se le realizó el mantenimiento.</td></tr><tr><td style="text-align:left;"><strong>DESCRIPCIÓN</strong></td><td style="text-align:left;">Una breve descripción de la acción realizada (ej: <strong>VULCANIZAR, DESARME Y ARME, ROTACION, COLOCACION, SACAR CUBIERTAS</strong>).</td></tr><tr><td style="text-align:left;"><strong>GOMERIA</strong></td><td style="text-align:left;">El nombre del taller o proveedor que realizó el trabajo (equivalente al filtro &quot;Proveedor&quot;).</td></tr><tr><td style="text-align:left;"><strong>NOTAS</strong></td><td style="text-align:left;"><strong>Información adicional y detallada</strong> relevante a la intervención (ej: &quot;SE VOLCANIZARON 2 GOMAS...&quot;, &quot;SE SACARON 2 MICHELIN DE...&quot;). Es crucial para entender el contexto completo.</td></tr><tr><td style="text-align:left;"><strong>Ofic. a actuar / Ofic. a actuar</strong></td><td style="text-align:left;">Parece ser un campo relacionado con la <strong>oficina o persona responsable</strong> de la acción.</td></tr><tr><td style="text-align:left;"><strong>VER MÁS</strong></td><td style="text-align:left;">Te muestra un reporte con los detalles del manteniemto <a href="./mantenimientosCubiertasDetalles.html">Ver Rerporte</a></td></tr></tbody></table><h2 id="_3-barra-superior-controles-globales" tabindex="-1">3. Barra Superior (Controles Globales) <a class="header-anchor" href="#_3-barra-superior-controles-globales" aria-label="Permalink to &quot;3. Barra Superior (Controles Globales)&quot;">​</a></h2><ul><li><strong>Paginación (Derecha):</strong> Indica en qué página del reporte te encuentras (ej: &quot;Página 1 de 2&quot;) y permite navegar entre ellas.</li><li><strong>Zoom (%):</strong> Permite cambiar el tamaño de visualización del reporte.</li><li><strong>Informe de búsqueda:</strong> Probablemente un botón para generar una <strong>versión imprimible o exportable</strong> (PDF, Excel) del reporte con los filtros aplicados.</li></ul><h2 id="¿como-usaria-este-reporte" tabindex="-1">¿Cómo usaría este reporte? <a class="header-anchor" href="#¿como-usaria-este-reporte" aria-label="Permalink to &quot;¿Cómo usaría este reporte?&quot;">​</a></h2><ol><li><strong>Buscar Mantenimiento de una Unidad Específica:</strong> Ingresaría el código de la unidad en el campo <strong>Unidad</strong> o la patente en el campo <strong>Referencia</strong> y haría clic en <strong>Aplicar</strong>.</li><li><strong>Ver Tareas de un Periodo:</strong> Borraría los campos de Unidad o Referencia, colocaría las fechas en <strong>fechaDesde</strong> y <strong>fechaHasta</strong>, y haría clic en <strong>Aplicar</strong>.</li><li><strong>Entender una Tarea a Fondo:</strong> Localizaría la intervención en la tabla y haría clic en <strong>VER MÁS</strong> para ver el detalle completo, incluyendo, posiblemente, el costo, las piezas específicas, y quién autorizó el trabajo.</li></ol>',12)]))}const p=t(n,[["render",l]]);export{m as __pageData,p as default};
